simple.c:
int add(int a, int b) {
    return a + b;
}

complex.c:
extern int table[100];
long compute(long a, long b, long c) {
    long temp = table[a] + b;
    table[c] = temp;
    return temp * a;
}

variadic.c:
int sum_ints(int count, ...) {
    va_list ap;
    va_start(ap, count);
    int total = 0;
    for (int i = 0; i < count; i++)
        total += va_arg(ap, int);
    va_end(ap);
    return total;
}
